CREATE UNIQUE INDEX swarms_live_name ON swarms(project_id, name) WHERE state <> 'deleted';
CREATE UNIQUE INDEX managed_pools_live_name ON managed_pools(name) WHERE state <> 'deleted';
CREATE UNIQUE INDEX managed_actors_live_name ON managed_actors(swarm_id, name) WHERE phase <> 'deleted';
CREATE UNIQUE INDEX managed_actors_live_ctid ON managed_actors(cluster_identity, ctid) WHERE phase <> 'deleted';
CREATE TRIGGER managed_swarm_delete_guard BEFORE DELETE ON swarms WHEN EXISTS (SELECT 1 FROM managed_actors WHERE swarm_id = OLD.id AND phase <> 'deleted') BEGIN SELECT RAISE(ABORT, 'swarm has managed actors'); END;
CREATE TRIGGER swarm_steps_report_fence BEFORE UPDATE ON swarm_steps WHEN NEW.report IS NOT OLD.report AND (OLD.report IS NOT NULL OR OLD.state = 'completed') BEGIN SELECT RAISE(ABORT, 'step report is written once with the outcome'); END;
CREATE TRIGGER swarm_steps_pass_fence BEFORE UPDATE ON swarm_steps WHEN NEW.goal IS NOT OLD.goal OR NEW.source_commit IS NOT OLD.source_commit BEGIN SELECT RAISE(ABORT, 'pass goal and commit are written once with the first step of the pass'); END;
CREATE TRIGGER pipeline_sources_immutable BEFORE UPDATE ON pipeline_sources BEGIN SELECT RAISE(ABORT, 'pipeline source is immutable'); END;
CREATE TRIGGER pipeline_sources_no_replace BEFORE INSERT ON pipeline_sources WHEN EXISTS (SELECT 1 FROM pipeline_sources WHERE swarm_id=NEW.swarm_id) BEGIN SELECT RAISE(ABORT, 'pipeline source is immutable'); END;
CREATE TRIGGER pipeline_sources_no_delete BEFORE DELETE ON pipeline_sources WHEN EXISTS (SELECT 1 FROM swarms WHERE id=OLD.swarm_id) BEGIN SELECT RAISE(ABORT, 'pipeline source is immutable'); END;
CREATE TRIGGER swarm_graph_immutable BEFORE UPDATE ON swarms WHEN OLD.graph IS NOT NULL AND (NEW.graph IS NOT OLD.graph OR NEW.definition_name IS NOT OLD.definition_name OR NEW.definition_version IS NOT OLD.definition_version OR NEW.definition_revision IS NOT OLD.definition_revision) BEGIN SELECT RAISE(ABORT, 'swarm graph is immutable'); END;
CREATE TRIGGER swarms_no_replace BEFORE INSERT ON swarms WHEN EXISTS (SELECT 1 FROM swarms WHERE id=NEW.id) BEGIN SELECT RAISE(ABORT, 'swarm already exists'); END;
CREATE TRIGGER swarm_steps_attested BEFORE UPDATE ON swarm_steps WHEN NEW.state IN ('delivering', 'inflight') AND EXISTS (SELECT 1 FROM pipeline_sources p WHERE p.swarm_id = NEW.swarm_id) AND COALESCE(NEW.source_commit, (SELECT s.source_commit FROM swarm_steps s WHERE s.swarm_id = NEW.swarm_id AND s.sequence <= NEW.sequence AND s.source_commit IS NOT NULL ORDER BY s.sequence DESC LIMIT 1)) IS NOT NEW.attested_commit BEGIN SELECT RAISE(ABORT, 'actor step requires a workspace attestation of its pass source'); END;
CREATE TRIGGER swarm_steps_attested_insert BEFORE INSERT ON swarm_steps WHEN NEW.state IN ('delivering', 'inflight') AND EXISTS (SELECT 1 FROM pipeline_sources p WHERE p.swarm_id = NEW.swarm_id) AND COALESCE(NEW.source_commit, (SELECT s.source_commit FROM swarm_steps s WHERE s.swarm_id = NEW.swarm_id AND s.sequence <= NEW.sequence AND s.source_commit IS NOT NULL ORDER BY s.sequence DESC LIMIT 1)) IS NOT NEW.attested_commit BEGIN SELECT RAISE(ABORT, 'actor step requires a workspace attestation of its pass source'); END;
CREATE UNIQUE INDEX swarm_requests_open_node ON swarm_requests(swarm_id) WHERE origin = 'node' AND state = 'open';
CREATE UNIQUE INDEX swarm_requests_step ON swarm_requests(swarm_id, sequence) WHERE origin = 'node';
CREATE INDEX swarm_requests_swarm ON swarm_requests(swarm_id);
CREATE TRIGGER swarm_requests_fence BEFORE UPDATE ON swarm_requests WHEN (OLD.state <> 'open' AND (NEW.state IS NOT OLD.state OR NEW.answered_at IS NOT OLD.answered_at OR NEW.answered_by IS NOT OLD.answered_by OR NEW.outcome IS NOT OLD.outcome OR NEW.response IS NOT OLD.response OR (NEW.delivery IS NOT OLD.delivery AND ((OLD.delivery IS NOT 'pending' AND OLD.delivery IS NOT 'failed' AND OLD.delivery IS NOT 'unconfirmed') OR NEW.delivery IS 'pending' OR (OLD.delivery IS 'unconfirmed' AND NEW.delivery IS 'failed'))))) OR NEW.id IS NOT OLD.id OR NEW.swarm_id IS NOT OLD.swarm_id OR NEW.sequence IS NOT OLD.sequence OR NEW.origin IS NOT OLD.origin OR NEW.actor_uid IS NOT OLD.actor_uid OR NEW.actor_incarnation IS NOT OLD.actor_incarnation OR NEW.kind IS NOT OLD.kind OR NEW.question IS NOT OLD.question OR NEW.context IS NOT OLD.context OR NEW.options IS NOT OLD.options OR NEW.created_at IS NOT OLD.created_at BEGIN SELECT RAISE(ABORT, 'swarm request is immutable'); END;
CREATE TRIGGER swarm_requests_no_delete BEFORE DELETE ON swarm_requests WHEN EXISTS (SELECT 1 FROM swarms WHERE id=OLD.swarm_id) BEGIN SELECT RAISE(ABORT, 'swarm request is permanent'); END;
CREATE TRIGGER swarm_requests_no_replace BEFORE INSERT ON swarm_requests WHEN EXISTS (SELECT 1 FROM swarm_requests WHERE id=NEW.id OR (NEW.origin='node' AND origin='node' AND swarm_id=NEW.swarm_id AND (sequence IS NEW.sequence OR (state='open' AND NEW.state='open')))) BEGIN SELECT RAISE(ABORT, 'swarm request is permanent'); END;
CREATE TRIGGER swarm_requests_cancel_guard BEFORE UPDATE OF state ON swarm_requests WHEN NEW.state = 'cancelled' AND OLD.origin = 'node' AND EXISTS (SELECT 1 FROM swarms WHERE id=OLD.swarm_id AND execution IN ('running', 'waiting')) BEGIN SELECT RAISE(ABORT, 'node request is closed by stopping the graph'); END;
CREATE TRIGGER swarms_gate_stop AFTER UPDATE OF execution ON swarms WHEN OLD.execution IN ('running', 'waiting') AND NEW.execution NOT IN ('running', 'waiting') BEGIN UPDATE swarm_requests SET state='cancelled' WHERE swarm_id=NEW.id AND origin='node' AND state='open'; END;
CREATE TRIGGER swarms_gate_resume BEFORE UPDATE OF execution ON swarms WHEN NEW.execution IN ('running', 'waiting') AND OLD.execution NOT IN ('running', 'waiting') AND EXISTS (SELECT 1 FROM swarm_steps s WHERE s.swarm_id=OLD.id AND s.state='waiting' AND NOT EXISTS (SELECT 1 FROM swarm_requests q WHERE q.swarm_id=s.swarm_id AND q.sequence=s.sequence AND q.origin='node' AND q.state='open')) BEGIN SELECT RAISE(ABORT, 'graph waits on a cancelled gate'); END;
CREATE INDEX telegram_outbox_pending ON telegram_outbox(user_id, id) WHERE state = 'pending';
CREATE INDEX telegram_outbox_user ON telegram_outbox(user_id);
CREATE TRIGGER telegram_outbox_insert BEFORE INSERT ON telegram_outbox WHEN NEW.state IS NOT 'pending' OR NEW.attempts IS NOT 0 OR NEW.settled_attempts IS NOT 0 OR NEW.telegram_message_id IS NOT NULL BEGIN SELECT RAISE(ABORT, 'telegram notification is queued pending'); END;
CREATE TRIGGER telegram_outbox_fence BEFORE UPDATE ON telegram_outbox WHEN NEW.id IS NOT OLD.id OR NEW.user_id IS NOT OLD.user_id OR NEW.kind IS NOT OLD.kind OR NEW.ref IS NOT OLD.ref OR NEW.payload IS NOT OLD.payload OR NEW.created_at IS NOT OLD.created_at OR NEW.attempts < OLD.attempts OR NEW.settled_attempts < OLD.settled_attempts OR (OLD.state = 'sent' AND (NEW.state IS NOT OLD.state OR NEW.attempts IS NOT OLD.attempts OR NEW.telegram_message_id IS NOT OLD.telegram_message_id OR NEW.updated_at IS NOT OLD.updated_at OR NEW.force_reply IS NOT OLD.force_reply)) BEGIN SELECT RAISE(ABORT, 'telegram notification is immutable'); END;
CREATE TRIGGER telegram_outbox_attempts BEFORE UPDATE ON telegram_outbox WHEN OLD.state <> 'sent' AND NOT (OLD.state = 'unconfirmed' AND NEW.state IN ('failed', 'pending')) AND ((NEW.attempts > OLD.attempts AND (OLD.attempts > OLD.settled_attempts OR NEW.settled_attempts IS NOT OLD.settled_attempts)) OR (NEW.settled_attempts > OLD.settled_attempts AND NEW.state = 'pending') OR (NEW.state IS NOT OLD.state AND NEW.settled_attempts = OLD.settled_attempts AND NOT (OLD.state = 'failed' AND NEW.state = 'pending'))) BEGIN SELECT RAISE(ABORT, 'telegram notification attempt is out of order'); END;
CREATE TRIGGER telegram_outbox_unconfirmed BEFORE UPDATE OF state ON telegram_outbox WHEN OLD.state = 'unconfirmed' AND NEW.state IN ('failed', 'pending') BEGIN SELECT RAISE(ABORT, 'unconfirmed telegram notification may have been sent'); END;
CREATE TRIGGER telegram_outbox_no_replace BEFORE INSERT ON telegram_outbox WHEN EXISTS (SELECT 1 FROM telegram_outbox WHERE id = NEW.id) BEGIN SELECT RAISE(ABORT, 'telegram notification already exists'); END;
CREATE TRIGGER telegram_outbox_no_delete BEFORE DELETE ON telegram_outbox WHEN EXISTS (SELECT 1 FROM users WHERE id = OLD.user_id) AND (OLD.state = 'pending' OR OLD.attempts > OLD.settled_attempts) BEGIN SELECT RAISE(ABORT, 'telegram notification is queued or in flight'); END;
CREATE TRIGGER telegram_outbox_fresh_id AFTER INSERT ON telegram_outbox WHEN NEW.id <= (SELECT seq FROM sqlite_sequence WHERE name = 'telegram_outbox') BEGIN SELECT RAISE(ABORT, 'telegram notification id is not new'); END;
CREATE TRIGGER sessions_telegram_revoke BEFORE DELETE ON sessions BEGIN UPDATE user_telegram_links SET state = 'error', reason = 'telegram session was revoked: link the chat again', chat_id = NULL, telegram_user_id = NULL, telegram_username = NULL, session_hash = NULL, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ', 'now') WHERE session_hash = OLD.token_hash; END;
CREATE TRIGGER gitlab_grants_fence BEFORE UPDATE ON gitlab_grants WHEN
 NEW.id IS NOT OLD.id OR NEW.project_id IS NOT OLD.project_id OR NEW.swarm_id IS NOT OLD.swarm_id OR
 NEW.atespace_uid IS NOT OLD.atespace_uid OR NEW.actor_uid IS NOT OLD.actor_uid OR NEW.incarnation IS NOT OLD.incarnation OR
 NEW.human_id IS NOT OLD.human_id OR NEW.binding_revision IS NOT OLD.binding_revision OR
 NEW.can_read IS NOT OLD.can_read OR NEW.can_create IS NOT OLD.can_create OR NEW.can_propose IS NOT OLD.can_propose OR
 NEW.expires_at IS NOT OLD.expires_at OR OLD.revoked != 0 OR NEW.revoked != 1 OR NEW.revision != OLD.revision + 1
 BEGIN SELECT RAISE(ABORT, 'GitLab grant is immutable except revocation'); END;
CREATE TRIGGER gitlab_operations_fence BEFORE UPDATE ON gitlab_operations WHEN
 NEW.id IS NOT OLD.id OR NEW.project_id IS NOT OLD.project_id OR NEW.swarm_id IS NOT OLD.swarm_id OR
 NEW.atespace_uid IS NOT OLD.atespace_uid OR NEW.actor_uid IS NOT OLD.actor_uid OR NEW.incarnation IS NOT OLD.incarnation OR
 NEW.kind IS NOT OLD.kind OR NEW.request_id IS NOT OLD.request_id OR NEW.grant_id IS NOT OLD.grant_id OR
 NEW.binding_revision IS NOT OLD.binding_revision OR NEW.binding_snapshot IS NOT OLD.binding_snapshot OR NEW.payload_hash IS NOT OLD.payload_hash OR NEW.snapshot IS NOT OLD.snapshot OR
 NEW.created_at IS NOT OLD.created_at OR NEW.revision != OLD.revision + 1 OR NOT (
 (OLD.state = 'reserved' AND NEW.state IN ('sending', 'refused')) OR
 (OLD.state = 'sending' AND NEW.state IN ('completed', 'refused', 'unknown')))
 BEGIN SELECT RAISE(ABORT, 'GitLab operation identity or transition is invalid'); END;
CREATE TRIGGER gitlab_approvals_fence BEFORE UPDATE ON gitlab_approvals WHEN
 NEW.operation_id IS NOT OLD.operation_id OR NEW.human_id IS NOT OLD.human_id OR NEW.session_hash IS NOT OLD.session_hash OR
 NEW.expires_at IS NOT OLD.expires_at OR OLD.state != 'approved' OR NEW.state NOT IN ('revoked', 'claimed') OR NEW.revision != OLD.revision + 1
 BEGIN SELECT RAISE(ABORT, 'GitLab approval is immutable except claim or revocation'); END;
CREATE TRIGGER gitlab_grants_no_delete BEFORE DELETE ON gitlab_grants BEGIN SELECT RAISE(ABORT, 'GitLab history cannot be deleted'); END;
CREATE TRIGGER gitlab_grants_no_replace BEFORE INSERT ON gitlab_grants WHEN EXISTS (SELECT 1 FROM gitlab_grants WHERE id=NEW.id) BEGIN SELECT RAISE(ABORT, 'GitLab history cannot be replaced'); END;
CREATE TRIGGER gitlab_operations_no_delete BEFORE DELETE ON gitlab_operations BEGIN SELECT RAISE(ABORT, 'GitLab history cannot be deleted'); END;
CREATE TRIGGER gitlab_operations_no_replace BEFORE INSERT ON gitlab_operations WHEN EXISTS (SELECT 1 FROM gitlab_operations WHERE id=NEW.id OR (project_id=NEW.project_id AND actor_uid=NEW.actor_uid AND incarnation=NEW.incarnation AND kind=NEW.kind AND request_id=NEW.request_id)) BEGIN SELECT RAISE(ABORT, 'GitLab history cannot be replaced'); END;
CREATE TRIGGER gitlab_approvals_no_delete BEFORE DELETE ON gitlab_approvals BEGIN SELECT RAISE(ABORT, 'GitLab history cannot be deleted'); END;
CREATE TRIGGER gitlab_approvals_no_replace BEFORE INSERT ON gitlab_approvals WHEN EXISTS (SELECT 1 FROM gitlab_approvals WHERE operation_id=NEW.operation_id) BEGIN SELECT RAISE(ABORT, 'GitLab history cannot be replaced'); END;
CREATE TRIGGER gitlab_proposal_states_fence BEFORE UPDATE ON gitlab_proposal_states WHEN
 NEW.operation_id IS NOT OLD.operation_id OR OLD.state != 'pending' OR NEW.state NOT IN ('rejected','stale') OR NEW.revision != OLD.revision+1
 BEGIN SELECT RAISE(ABORT, 'GitLab proposal decision is terminal'); END;
CREATE TRIGGER gitlab_proposal_states_no_delete BEFORE DELETE ON gitlab_proposal_states
 BEGIN SELECT RAISE(ABORT, 'GitLab proposal history cannot be deleted'); END;
CREATE TRIGGER gitlab_proposal_states_no_replace BEFORE INSERT ON gitlab_proposal_states WHEN EXISTS (SELECT 1 FROM gitlab_proposal_states WHERE operation_id=NEW.operation_id)
 BEGIN SELECT RAISE(ABORT, 'GitLab proposal history cannot be replaced'); END;
CREATE UNIQUE INDEX swarm_child_running_actor ON swarm_child_tasks(actor_uid) WHERE state='running';
CREATE INDEX swarm_child_queue_actor ON swarm_child_tasks(actor_uid,state,delivery);
CREATE INDEX actor_interventions_actor ON actor_interventions(actor_uid,state);
CREATE TRIGGER actor_interventions_fence BEFORE UPDATE ON actor_interventions WHEN
 NEW.id IS NOT OLD.id OR NEW.project_id IS NOT OLD.project_id OR NEW.swarm_id IS NOT OLD.swarm_id OR NEW.actor_uid IS NOT OLD.actor_uid OR NEW.incarnation IS NOT OLD.incarnation OR NEW.human_id IS NOT OLD.human_id OR NEW.caller IS NOT OLD.caller OR NEW.operation IS NOT OLD.operation OR NEW.created_at IS NOT OLD.created_at
 OR OLD.state!='inflight' OR NEW.state NOT IN ('completed','unconfirmed')
 BEGIN SELECT RAISE(ABORT,'owner intervention identity and settled history are immutable'); END;
CREATE TRIGGER actor_interventions_no_delete BEFORE DELETE ON actor_interventions BEGIN SELECT RAISE(ABORT,'owner intervention history is retained'); END;
CREATE TRIGGER actor_step_interruptions_fence BEFORE UPDATE ON actor_step_interruptions BEGIN SELECT RAISE(ABORT,'step interruption history is immutable'); END;
CREATE TRIGGER actor_step_interruptions_no_delete BEFORE DELETE ON actor_step_interruptions BEGIN SELECT RAISE(ABORT,'step interruption history is retained'); END;
CREATE TRIGGER swarm_steps_owner_interruption BEFORE UPDATE ON swarm_steps WHEN
 (NEW.state IN ('completed','answered','stopped','refused') OR NEW.finished_at IS NOT NULL OR NEW.outcome IS NOT OLD.outcome)
 AND EXISTS(SELECT 1 FROM actor_step_interruptions i WHERE i.swarm_id=OLD.swarm_id AND i.sequence=OLD.sequence)
 BEGIN SELECT RAISE(ABORT,'owner-interrupted execution requires explicit reconciliation'); END;
CREATE TRIGGER swarm_child_joins_insert BEFORE INSERT ON swarm_child_joins BEGIN
 SELECT CASE WHEN NEW.state!='open' OR NEW.revision!=1 OR NEW.aborted_by IS NOT NULL OR NEW.aborted_at IS NOT NULL THEN RAISE(ABORT,'child join starts open') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM swarm_child_joins WHERE swarm_id=NEW.swarm_id AND parent_sequence=NEW.parent_sequence) THEN RAISE(ABORT,'child join already exists') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM swarm_steps p JOIN swarms sw ON sw.id=p.swarm_id
 WHERE p.swarm_id=NEW.swarm_id AND p.sequence=NEW.parent_sequence AND p.actor_uid=NEW.parent_uid AND p.actor_incarnation=NEW.parent_incarnation AND p.request_id=NEW.parent_request_id
 AND p.state IN ('delivering','inflight','unconfirmed') AND p.attested_commit IS NOT NULL
 AND p.sequence=(SELECT MAX(sequence) FROM swarm_steps WHERE swarm_id=p.swarm_id)
 AND NEW.pass=(SELECT MAX(sequence) FROM swarm_steps WHERE swarm_id=p.swarm_id AND sequence<=p.sequence AND goal IS NOT NULL)
 AND sw.project_id=NEW.project_id AND sw.atespace_uid=NEW.atespace_uid AND sw.state='active' AND sw.execution IN ('running','waiting')) THEN RAISE(ABORT,'child join requires the current parent attempt') END;
 END;
CREATE TRIGGER swarm_child_joins_immutable BEFORE UPDATE ON swarm_child_joins WHEN
 NEW.swarm_id IS NOT OLD.swarm_id OR NEW.parent_sequence IS NOT OLD.parent_sequence OR NEW.pass IS NOT OLD.pass OR NEW.project_id IS NOT OLD.project_id OR NEW.atespace_uid IS NOT OLD.atespace_uid OR NEW.parent_uid IS NOT OLD.parent_uid OR NEW.parent_incarnation IS NOT OLD.parent_incarnation OR NEW.parent_request_id IS NOT OLD.parent_request_id OR NEW.mode IS NOT OLD.mode OR NEW.total IS NOT OLD.total OR NEW.quorum IS NOT OLD.quorum OR NEW.remaining IS NOT OLD.remaining OR NEW.created_at IS NOT OLD.created_at
 OR OLD.state!='open' OR NEW.state!='aborted' OR NEW.revision!=OLD.revision+1
 OR (SELECT count(*) FROM swarm_child_tasks c WHERE c.swarm_id=OLD.swarm_id AND c.parent_sequence=OLD.parent_sequence)>=OLD.total
 OR EXISTS(SELECT 1 FROM swarm_child_tasks c WHERE c.swarm_id=OLD.swarm_id AND c.parent_sequence=OLD.parent_sequence AND c.state!='cancelled')
 BEGIN SELECT RAISE(ABORT,'child join identity and policy are immutable; only incomplete unstarted abort is allowed'); END;
CREATE TRIGGER swarm_child_joins_no_delete BEFORE DELETE ON swarm_child_joins BEGIN SELECT RAISE(ABORT,'child join history is retained'); END;
CREATE TRIGGER swarm_child_tasks_insert BEFORE INSERT ON swarm_child_tasks BEGIN
 SELECT CASE WHEN EXISTS(SELECT 1 FROM swarm_child_tasks WHERE id=NEW.id OR (swarm_id=NEW.swarm_id AND parent_sequence=NEW.parent_sequence AND request_id=NEW.request_id)) THEN RAISE(ABORT,'child request already exists') END;
 SELECT CASE WHEN NEW.state!='pending' OR NEW.revision!=1 OR NEW.outcome IS NOT NULL OR NEW.report IS NOT NULL OR NEW.finished_at IS NOT NULL THEN RAISE(ABORT,'child starts as pending intent') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM swarm_child_joins j WHERE j.swarm_id=NEW.swarm_id AND j.parent_sequence=NEW.parent_sequence AND j.state='open' AND (SELECT count(*) FROM swarm_child_tasks c WHERE c.swarm_id=j.swarm_id AND c.parent_sequence=j.parent_sequence)<j.total) THEN RAISE(ABORT,'child join membership is full or missing') END;
 END;
CREATE TRIGGER swarm_child_tasks_fence BEFORE UPDATE ON swarm_child_tasks WHEN
 NEW.id IS NOT OLD.id OR NEW.swarm_id IS NOT OLD.swarm_id OR NEW.parent_sequence IS NOT OLD.parent_sequence OR NEW.request_id IS NOT OLD.request_id OR NEW.payload IS NOT OLD.payload OR NEW.actor_uid IS NOT OLD.actor_uid OR NEW.actor_incarnation IS NOT OLD.actor_incarnation OR NEW.created_at IS NOT OLD.created_at
 OR NEW.role IS NOT OLD.role OR NEW.revision!=OLD.revision+1 OR NOT (
 ((OLD.state='pending' AND NEW.state='running' AND ((OLD.delivery='' AND NEW.delivery='') OR (OLD.delivery='queued' AND NEW.delivery='sending')))
 OR (OLD.state='pending' AND NEW.state='cancelled' AND NEW.delivery=OLD.delivery)
 OR (OLD.state='running' AND NEW.state='completed' AND OLD.delivery!='not_sent' AND (NEW.delivery=OLD.delivery OR (OLD.delivery IN ('sending','unconfirmed') AND NEW.delivery='delivered')))
 OR (OLD.state='running' AND NEW.state='cancelled' AND OLD.delivery='not_sent' AND NEW.delivery=OLD.delivery)) AND (NEW.delivery_detail=OLD.delivery_detail OR (OLD.state='running' AND NEW.state='completed' AND NEW.delivery='delivered'))
 OR (OLD.state='running' AND NEW.state=OLD.state AND OLD.delivery='sending' AND NEW.delivery IN ('delivered','not_sent','unconfirmed') AND NEW.outcome IS OLD.outcome AND NEW.report IS OLD.report AND NEW.finished_at IS OLD.finished_at))
 OR EXISTS(SELECT 1 FROM swarm_child_joins j WHERE j.swarm_id=OLD.swarm_id AND j.parent_sequence=OLD.parent_sequence AND j.state!='open')
 BEGIN SELECT RAISE(ABORT,'child identity, payload and terminal result are immutable'); END;
CREATE TRIGGER swarm_child_tasks_no_delete BEFORE DELETE ON swarm_child_tasks BEGIN SELECT RAISE(ABORT,'child task history is retained'); END;
CREATE TRIGGER swarm_steps_child_identity BEFORE UPDATE ON swarm_steps WHEN EXISTS(SELECT 1 FROM swarm_child_joins j WHERE j.swarm_id=OLD.swarm_id AND j.parent_sequence=OLD.sequence) AND (NEW.swarm_id IS NOT OLD.swarm_id OR NEW.sequence IS NOT OLD.sequence OR NEW.actor_uid IS NOT OLD.actor_uid OR NEW.actor_incarnation IS NOT OLD.actor_incarnation OR NEW.request_id IS NOT OLD.request_id OR NEW.node_id IS NOT OLD.node_id OR NEW.attested_commit IS NOT OLD.attested_commit) BEGIN SELECT RAISE(ABORT,'child parent identity is immutable'); END;
CREATE TRIGGER swarm_steps_child_close BEFORE UPDATE ON swarm_steps WHEN (NEW.state IN ('completed','answered','stopped','refused') OR NEW.finished_at IS NOT NULL OR NEW.outcome IS NOT OLD.outcome) AND EXISTS(SELECT 1 FROM swarm_child_joins j WHERE j.swarm_id=OLD.swarm_id AND j.parent_sequence=OLD.sequence AND ((j.state!='aborted' AND EXISTS(SELECT 1 FROM actor_step_interruptions i WHERE i.swarm_id=j.swarm_id AND i.sequence=j.parent_sequence)) OR (j.state!='aborted' AND (SELECT count(*) FROM swarm_child_tasks c WHERE c.swarm_id=j.swarm_id AND c.parent_sequence=j.parent_sequence)<j.total) OR EXISTS(SELECT 1 FROM swarm_child_tasks c WHERE c.swarm_id=j.swarm_id AND c.parent_sequence=j.parent_sequence AND c.state IN ('pending','running')))) BEGIN SELECT RAISE(ABORT,'unfinished children protect the parent step'); END;
CREATE TRIGGER swarm_steps_child_delete BEFORE DELETE ON swarm_steps WHEN EXISTS(SELECT 1 FROM swarm_child_joins j WHERE j.swarm_id=OLD.swarm_id AND (j.parent_sequence=OLD.sequence OR j.pass=OLD.sequence)) BEGIN SELECT RAISE(ABORT,'child parent history is retained'); END;
CREATE TRIGGER swarm_steps_child_insert BEFORE INSERT ON swarm_steps WHEN EXISTS(SELECT 1 FROM swarm_child_joins j WHERE j.swarm_id=NEW.swarm_id AND (j.parent_sequence=NEW.sequence OR ((j.state!='aborted' AND EXISTS(SELECT 1 FROM actor_step_interruptions i WHERE i.swarm_id=j.swarm_id AND i.sequence=j.parent_sequence)) OR (j.state!='aborted' AND (SELECT count(*) FROM swarm_child_tasks c WHERE c.swarm_id=j.swarm_id AND c.parent_sequence=j.parent_sequence)<j.total) OR EXISTS(SELECT 1 FROM swarm_child_tasks c WHERE c.swarm_id=j.swarm_id AND c.parent_sequence=j.parent_sequence AND c.state IN ('pending','running'))))) BEGIN SELECT RAISE(ABORT,'unfinished children protect parent progression'); END;
CREATE TRIGGER swarms_child_close BEFORE UPDATE ON swarms WHEN (NEW.execution NOT IN ('running','waiting') OR NEW.state IN ('deleting','deleted')) AND EXISTS(SELECT 1 FROM swarm_child_joins j WHERE j.swarm_id=OLD.id AND ((j.state!='aborted' AND EXISTS(SELECT 1 FROM actor_step_interruptions i WHERE i.swarm_id=j.swarm_id AND i.sequence=j.parent_sequence)) OR (j.state!='aborted' AND (SELECT count(*) FROM swarm_child_tasks c WHERE c.swarm_id=j.swarm_id AND c.parent_sequence=j.parent_sequence)<j.total) OR EXISTS(SELECT 1 FROM swarm_child_tasks c WHERE c.swarm_id=j.swarm_id AND c.parent_sequence=j.parent_sequence AND c.state IN ('pending','running'))) AND NOT (NEW.execution='stopped' AND NEW.state='active' AND EXISTS(SELECT 1 FROM actor_step_interruptions i JOIN actor_interventions a ON a.id=i.intervention_id WHERE i.swarm_id=j.swarm_id AND i.sequence=j.parent_sequence AND a.operation='pass_stop' AND a.state='completed'))) BEGIN SELECT RAISE(ABORT,'unfinished children protect the parent pass'); END;
CREATE TRIGGER managed_actor_networks_no_update BEFORE UPDATE ON managed_actor_networks BEGIN SELECT RAISE(ABORT, 'managed actor network snapshot is immutable'); END;
CREATE TRIGGER managed_actor_networks_no_delete BEFORE DELETE ON managed_actor_networks BEGIN SELECT RAISE(ABORT, 'managed actor network snapshot is immutable'); END;
CREATE TRIGGER managed_actor_networks_no_replace BEFORE INSERT ON managed_actor_networks WHEN EXISTS (SELECT 1 FROM managed_actor_networks WHERE actor_uid=NEW.actor_uid) BEGIN SELECT RAISE(ABORT, 'managed actor network snapshot is immutable'); END;
PRAGMA user_version=36;
COMMIT;
